fast_pseudocode:
# Autotuned tile config, >1-wave occupancy
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 1024, 'YBLOCK': 1}, num_warps=8),
        triton.Config({'XBLOCK': 512,  'YBLOCK': 1}, num_warps=4),
        triton.Config({'XBLOCK': 256,  'YBLOCK': 1}, num_warps=4),
        triton.Config({'XBLOCK': 256,  'YBLOCK': 2}, num_warps=4),
        triton.Config({'XBLOCK': 128,  'YBLOCK': 4}, num_warps=4),
        triton.Config({'XBLOCK': 128,  'YBLOCK': 8}, num_warps=2),
    ],
    key=['ynumel', 'xnumel'],
)
@triton.jit
def kernel(..., YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    ...

def launch():
    grid = lambda META: (cdiv(xnumel, META['XBLOCK']), cdiv(ynumel, META['YBLOCK']))
    kernel[grid](...)  # autotuner picks best config -> 1.48 waves/SM
